from lib import *
S = SS('l16')
steps = [
    step("造 20 个 pack:每次提交 150 个新文件,然后 git repack -d(只把松散对象打成一个新 pack,不合并旧 pack)。20 次后 ls 数出 20 个 pack,松散对象 count: 0,in-pack: 3060,packs: 20。(这个实验所在的 HOME 里把 maintenance.auto 关掉了:默认配置下每次 git commit 之后 git 会在后台运行 git maintenance run --auto,在松散对象多的时候悄悄重新打包、合并 pack,pack 数就不会一路涨到 20。)", t=tl(S(1)), mark=lidx(S(1), 'packs: 20'), done=lidx(S(1), 'in-pack: 3060', 'count: 0'), kv=KV([['repack -d', '只打包松散对象,每次产生一个新 pack'], ['20 个 pack', '3060 个对象分散在 20 个 idx 里'], ['注意', '默认配置下 commit 后会自动维护']], ['20 个 pack'])),
    step("git multi-pack-index write 在 pack 目录里新增一个文件 multi-pack-index,87,796 字节。头部:签名 MIDX、版本 1、哈希版本 1(SHA-1)、4 个块、基础 midx 0 个、pack 数 20。接着是块表,每个块 12 字节(4 字节名字 + 8 字节偏移):PNAM(偏移 72,长 1000)、OIDF(偏移 1072,长 1024)、OIDL(偏移 2096,长 61200)、OOFF(偏移 63296,长 24480)。", t=tl(S(2)), mark=lidx(S(2), '签名', '块 PNAM', '块 OIDF', '块 OIDL', '块 OOFF'), done=lidx(S(2), 'multi-pack-index write', '0000  4d 49 44 58'), kv=KV([['头部', 'MIDX + 版本 + 哈希版本 + 块数 + pack 数'], ['块', 'PNAM / OIDF / OIDL / OOFF'], ['大小', '87,796 字节 / 3060 个对象']], ['块'])),
    step("四个块:PNAM 是 20 个 pack 的 idx 文件名(字典序);OIDF 是整个 midx 的 fanout,末项 3060 恰好等于各个 pack 的 in-pack 之和(没有重复对象);OIDL 是所有 pack 合并后升序的 hash 表(验证 True);OOFF 每项 8 字节,记 pack 编号与 pack 内偏移。查目标 ee29687a…:OOFF 给出 pack 19 的偏移 3838,与该 pack 里 git verify-pack 给出的偏移 3838 一致。git multi-pack-index verify 退出码 0。", t=tl(S(3)), mark=lidx(S(3), 'OOFF 里 pack 编号 19', '偏移 3838  一致'), done=lidx(S(3), 'PNAM:20', 'OIDF 末项', 'OIDL 升序排列', 'verify 退出码 0'), kv=KV([['PNAM', 'pack 名字表'], ['OIDF / OIDL', '全局 fanout 与 hash 表'], ['OOFF', '(pack 编号, 偏移) 对,每对象 8 字节']], ['OOFF'])),
    step("速度:用 git cat-file --batch-check 查全部 3060 个对象,9 次中位数,20 个 pack 使用 midx 是 14.3 ms,core.multiPackIndex=false 不使用 midx 是 14.6 ms,几乎一样。查找 3060 个对象在 20 个 pack 的规模下,没有 midx 也不慢;midx 的价值在 pack 数量大得多时,以及位图等功能需要一个统一的对象顺序。", t=tl(S(4)), mark=lidx(S(4), '不使用 midx'), done=lidx(S(4), '使用 midx : 14.3'), b=bars([['使用 midx', 14.3, '14.3 ms'], ['不使用 midx', 14.6, '14.6 ms']], 14.6, mark=[0], done=[1]), kv=KV([['20 个 pack、3060 个对象', '有无 midx 无差别'], ['midx 的价值', '大量 pack,以及位图等需要全局顺序的功能'], ['限制', '没有测几百个 pack']], ['限制'])),
    step("git multi-pack-index repack 把一批小 pack 重新打成一个新 pack:--batch-size=1 没有产生新 pack,仍是 20 个;--batch-size=30000 产生了第 21 个 pack,再 expire(删除对象已被其它 pack 完全覆盖的旧 pack)后剩 17 个,verify 通过,对象数仍是 3060;再 --batch-size=60000 产生第 18 个,expire 后剩 11 个。每次合并掉 4 个、7 个旧 pack,而不需要重写全部对象。", t=tl(S(5)), mark=lidx(S(5), '--batch-size=30000', '--batch-size=60000'), done=lidx(S(5), '--batch-size=1;', 'packs: 17', 'packs: 11'), b=bars([['开始', 20, '20 个 pack'], ['batch-size=30000 + expire', 17, '17 个'], ['batch-size=60000 + expire', 11, '11 个']], 20, mark=[2], done=[0, 1]), kv=KV([['repack', '把选中的小 pack 合并成新 pack'], ['expire', '删除已被覆盖的旧 pack'], ['batch-size', '决定一次合并多少个(这里 30000 → 4 个,60000 → 7 个)']], ['batch-size'])),
]
A = mkarti('l16', 16, 'Git,multi-pack-index,midx,packfile,repack,真实验证,动画演示',
    '实测 multi-pack-index:20 个 pack 写出一个 87,796 字节的 midx,解析头部(MIDX、版本 1)与 PNAM、OIDF、OIDL、OOFF 四个块,偏移与 git verify-pack 一致;20 个 pack 下有无 midx 查全部对象耗时都是 14 ms 左右;multi-pack-index repack --batch-size 配合 expire 把 pack 从 20 个合并到 17、11 个;默认配置下 commit 后的自动维护会悄悄合并 pack。',
    'multi-pack-index 是什么,为什么 pack 一多 git 就需要它?这篇造 20 个小 pack,解析 midx 文件的头部和四个块,验证偏移,测有无 midx 的查找耗时,再用 multi-pack-index repack 与 expire 把小 pack 合并。',
    [('20 → 11', '多次 multi-pack-index repack 与 expire 之后 pack 的数量,对象数始终 3060'), ('4 个块', 'midx 里的 PNAM、OIDF、OIDL、OOFF,合起来为 20 个 pack 提供一张统一的索引'), ('14.3 vs 14.6 ms', '20 个 pack 下有无 midx 查全部 3060 个对象的耗时,几乎无差别')],
    [('为什么需要', '<p>每个 pack 有自己的 .idx,查一个对象要依次在多个 idx 里找。<code>multi-pack-index</code> 把所有 pack 的对象放进一张全局索引:去重的 hash 表、全局 fanout、每个对象所在的 pack 和偏移,查一次就知道在哪。</p>'),
     ('文件结构', '<p>头部 12 字节:签名 <code>MIDX</code>、版本、哈希版本、块数、基础 midx 数、pack 数;然后是块表(每个块的 4 字节 id 加 8 字节偏移),再是 <code>PNAM</code>(pack 名字)、<code>OIDF</code>(fanout)、<code>OIDL</code>(hash 表)、<code>OOFF</code>(pack 编号加偏移)。</p>'),
     ('对账', '<p>midx 里记录的 pack 编号与偏移,和 <code>git verify-pack</code> 给出的偏移完全一致;<code>git multi-pack-index verify</code> 通过。</p>'),
     ('速度', '<p>本例 20 个 pack、3060 个对象,有没有 midx 查找耗时没有差别。midx 的价值在于 pack 很多的大仓库,以及位图等需要统一对象顺序的功能(见后面 reachability bitmap 一篇)。</p>'),
     ('合并小 pack', '<p><code>multi-pack-index repack --batch-size=N</code> 选出一批小 pack 合成一个新 pack,<code>expire</code> 再删除对象已被完全覆盖的旧 pack。不需要像 <code>git gc</code> 那样重写全部对象,适合大仓库的增量维护。</p>')],
    steps,
    [ENV_I_GIT + '。HOME 里的全局配置关闭了 maintenance.auto 和 gc.auto,否则 git commit 后会自动触发后台维护;pack 由 git repack -d 逐个生成;midx 由我用 Python 按字节解析,对账对象是 git verify-pack 与 git multi-pack-index verify;速度是 9 次中位数',
     '没有验证:几百个 pack 以上时 midx 的查找优势;incremental midx(基础 midx 链,本例基础数为 0);--preferred-pack 与 bitmap;LOFF 块(超过 2 GB 的偏移);batch-size 如何挑选 pack 的具体规则(只记录了本例的结果);默认配置下自动维护合并 pack 的触发条件(只观察到现象)'],
    'multi-pack-index')
